-- SQLite development schema v001. UTC ISO-8601 timestamps; reporting uses Asia/Shanghai.
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version TEXT PRIMARY KEY);
INSERT OR IGNORE INTO schema_migrations VALUES ('001');
CREATE TABLE IF NOT EXISTS teams(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, team_id TEXT NOT NULL REFERENCES teams(id), name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('operator','consultant','supervisor','admin')), password_hash TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)), session_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS dictionaries(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN('disease','channel','region','invalid_reason','transfer_reason','campus','project')), name TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, UNIQUE(kind,name));
CREATE TABLE IF NOT EXISTS source_accounts(id TEXT PRIMARY KEY, channel_id TEXT NOT NULL REFERENCES dictionaries(id), operator_id TEXT NOT NULL REFERENCES users(id), account_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS consultant_profiles(user_id TEXT PRIMARY KEY REFERENCES users(id), weight INTEGER NOT NULL DEFAULT 1 CHECK(weight BETWEEN 1 AND 10), daily_capacity INTEGER NOT NULL DEFAULT 20 CHECK(daily_capacity>0), active_capacity INTEGER NOT NULL DEFAULT 50 CHECK(active_capacity>0), on_duty INTEGER NOT NULL DEFAULT 0, blocked INTEGER NOT NULL DEFAULT 0, last_assigned_at TEXT);
CREATE TABLE IF NOT EXISTS consultant_skills(user_id TEXT REFERENCES users(id), disease_id TEXT REFERENCES dictionaries(id), PRIMARY KEY(user_id,disease_id));
CREATE TABLE IF NOT EXISTS consultant_regions(user_id TEXT REFERENCES users(id), region_id TEXT REFERENCES dictionaries(id), PRIMARY KEY(user_id,region_id));
CREATE TABLE IF NOT EXISTS leads(id TEXT PRIMARY KEY, lead_no TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, team_id TEXT NOT NULL REFERENCES teams(id), operator_id TEXT NOT NULL REFERENCES users(id), disease_id TEXT NOT NULL REFERENCES dictionaries(id), channel_id TEXT NOT NULL REFERENCES dictionaries(id), region_id TEXT NOT NULL REFERENCES dictionaries(id), source_account_id TEXT REFERENCES source_accounts(id), source_video TEXT, platform_lead_id TEXT, nickname TEXT, contact_ciphertext BLOB NOT NULL, contact_key_version TEXT NOT NULL, contact_hmac TEXT NOT NULL, consultant_id TEXT REFERENCES users(id), status TEXT NOT NULL CHECK(status IN('pending_assignment','pending_acceptance','accepted','wechat_added','followup_pending','booked','visited','converted','invalid','duplicate_review')), duplicate_of TEXT REFERENCES leads(id), invalid_reason_id TEXT REFERENCES dictionaries(id), version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS ix_leads_contact ON leads(contact_hmac);
CREATE INDEX IF NOT EXISTS ix_leads_operator ON leads(operator_id,created_at);
CREATE INDEX IF NOT EXISTS ix_leads_consultant ON leads(consultant_id,status);
CREATE TABLE IF NOT EXISTS assignments(id TEXT PRIMARY KEY, lead_id TEXT NOT NULL REFERENCES leads(id), from_user_id TEXT REFERENCES users(id), to_user_id TEXT NOT NULL REFERENCES users(id), actor_id TEXT REFERENCES users(id), assigned_at TEXT NOT NULL, accepted_at TEXT, ended_at TEXT, reason TEXT NOT NULL, rule_snapshot_json TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS ix_assignment_active ON assignments(lead_id) WHERE ended_at IS NULL;
CREATE TABLE IF NOT EXISTS status_events(id TEXT PRIMARY KEY, lead_id TEXT NOT NULL REFERENCES leads(id), actor_id TEXT NOT NULL REFERENCES users(id), from_status TEXT, to_status TEXT NOT NULL, occurred_at TEXT NOT NULL, result_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS followups(id TEXT PRIMARY KEY, lead_id TEXT NOT NULL REFERENCES leads(id), owner_id TEXT NOT NULL REFERENCES users(id), due_at TEXT NOT NULL, completed_at TEXT, result TEXT);
CREATE TABLE IF NOT EXISTS appointments(id TEXT PRIMARY KEY, lead_id TEXT NOT NULL REFERENCES leads(id), campus_id TEXT NOT NULL REFERENCES dictionaries(id), scheduled_at TEXT NOT NULL, arrived_at TEXT, verified_by TEXT REFERENCES users(id), cancelled_at TEXT);
CREATE TABLE IF NOT EXISTS deals(id TEXT PRIMARY KEY, lead_id TEXT NOT NULL REFERENCES leads(id), project_id TEXT NOT NULL REFERENCES dictionaries(id), amount_fen INTEGER NOT NULL CHECK(amount_fen>=0), refund_fen INTEGER NOT NULL DEFAULT 0 CHECK(refund_fen>=0 AND refund_fen<=amount_fen), occurred_at TEXT NOT NULL, verified_by TEXT REFERENCES users(id), verified_at TEXT);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, occurred_at TEXT NOT NULL, metadata_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS import_jobs(id TEXT PRIMARY KEY, operator_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, status TEXT NOT NULL, success_count INTEGER NOT NULL DEFAULT 0, failure_count INTEGER NOT NULL DEFAULT 0, error_report_path TEXT);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, recipient_id TEXT NOT NULL REFERENCES users(id), lead_id TEXT REFERENCES leads(id), kind TEXT NOT NULL, created_at TEXT NOT NULL, read_at TEXT, idempotency_key TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value_json TEXT NOT NULL);
INSERT OR IGNORE INTO settings VALUES('accept_timeout_minutes','5'),('first_contact_timeout_minutes','15');
